// ─────────────────────────────────────────────────────────────
// LOAD TEST MOCK — 10 bookings per therapist, 147 therapists
// ─────────────────────────────────────────────────────────────
//
// DATE CONTROL
// By default shows TODAY. To test a specific date, set MOCK_DATE_OVERRIDE:
//   const MOCK_DATE_OVERRIDE = "03-04-2026";   // DD-MM-YYYY format
//   const MOCK_DATE_OVERRIDE = null;            // use today
//
// const MOCK_DATE_OVERRIDE = "03-04-2026"; //null - current date, for specific date: "03-04-2026";
const MOCK_DATE_OVERRIDE = "03-04-2026";

const _today = new Date();
const _pad = n => String(n).padStart(2, "0");
export const MOCK_DATE = MOCK_DATE_OVERRIDE ||
  `${_pad(_today.getDate())}-${_pad(_today.getMonth() + 1)}-${_today.getFullYear()}`;

const mockDate = MOCK_DATE; // alias used inside the array below

